const listRecentComments = `-- name: ListRecentComments :many
SELECT vc.id, vc.video_id, vc.user_id, vc.parent_id, vc.body, vc.pinned, vc.created_at, vc.updated_at, u.name AS author_name, u.kind AS author_kind, v.title AS video_title, c.id AS course_id, c.title AS course_title,
       count(*) OVER () AS total_count
FROM video_comments vc
JOIN users u ON u.id = vc.user_id
JOIN videos v ON v.id = vc.video_id
JOIN courses c ON c.id = v.course_id
WHERE ($1::uuid IS NULL OR c.id IN (SELECT mentor_course_ids($1)))
  AND (NOT $2::boolean OR (vc.parent_id IS NULL AND u.kind = 'student' AND NOT EXISTS (
        SELECT 1 FROM video_comments r JOIN users ru ON ru.id = r.user_id WHERE r.parent_id = vc.id AND ru.kind = 'staff')))
ORDER BY vc.created_at DESC
LIMIT $4::int OFFSET $3::int
`

